/// A fixed-capacity least-recently-used cache with O(1) expected-time operations.
///
/// Entries live in a contiguous node pool linked into a doubly linked recency list
/// by index, so no per-entry heap allocation or reference counting is needed.
/// Slots freed by deletion are recycled through a free list.
struct LRUCache<Key: Hashable, Value> {
    private struct Node {
        var key: Key
        var value: Value
        var prev: Int
        var next: Int
    }

    private static var none: Int { -1 }

    let capacity: Int
    private var index: [Key: Int]
    private var nodes: [Node] = []
    private var freeSlots: [Int] = []
    /// Most recently used entry.
    private var head = LRUCache.none
    /// Least recently used entry.
    private var tail = LRUCache.none

    init(capacity: Int) {
        precondition(capacity > 0, "LRU capacity must be positive")
        self.capacity = capacity
        self.index = Dictionary(minimumCapacity: min(capacity, 1 << 16))
    }

    var count: Int { index.count }

    /// Returns the value for `key`, marking it most recently used on a hit.
    mutating func value(forKey key: Key) -> Value? {
        guard let slot = index[key] else { return nil }
        moveToFront(slot)
        return nodes[slot].value
    }

    /// Inserts or overwrites `key`, marking it most recently used and evicting
    /// the least recently used entry if the capacity is exceeded.
    mutating func setValue(_ value: Value, forKey key: Key) {
        if let slot = index[key] {
            nodes[slot].value = value
            moveToFront(slot)
            return
        }
        let node = Node(key: key, value: value, prev: Self.none, next: Self.none)
        let slot: Int
        if let reused = freeSlots.popLast() {
            nodes[reused] = node
            slot = reused
        } else {
            slot = nodes.count
            nodes.append(node)
        }
        index[key] = slot
        pushFront(slot)
        if index.count > capacity {
            evictLeastRecentlyUsed()
        }
    }

    /// Removes `key`, returning whether it was present.
    @discardableResult
    mutating func removeValue(forKey key: Key) -> Bool {
        guard let slot = index.removeValue(forKey: key) else { return false }
        unlink(slot)
        freeSlots.append(slot)
        return true
    }

    // MARK: - Recency list

    private mutating func evictLeastRecentlyUsed() {
        let slot = tail
        guard slot != Self.none else { return }
        index.removeValue(forKey: nodes[slot].key)
        unlink(slot)
        freeSlots.append(slot)
    }

    private mutating func moveToFront(_ slot: Int) {
        guard slot != head else { return }
        unlink(slot)
        pushFront(slot)
    }

    private mutating func pushFront(_ slot: Int) {
        nodes[slot].prev = Self.none
        nodes[slot].next = head
        if head != Self.none {
            nodes[head].prev = slot
        } else {
            tail = slot
        }
        head = slot
    }

    private mutating func unlink(_ slot: Int) {
        let prev = nodes[slot].prev
        let next = nodes[slot].next
        if prev != Self.none {
            nodes[prev].next = next
        } else {
            head = next
        }
        if next != Self.none {
            nodes[next].prev = prev
        } else {
            tail = prev
        }
        nodes[slot].prev = Self.none
        nodes[slot].next = Self.none
    }
}

/// Reads an LRU capacity followed by cache commands from standard input and
/// writes each command's result to standard output.

/// Collects output lines and flushes them to stdout in large chunks.
struct OutputBuffer {
    private var buffer = ""
    private let flushThreshold = 1 << 16

    mutating func writeLine(_ line: some StringProtocol) {
        buffer.append(contentsOf: line)
        buffer.append("\n")
        if buffer.utf8.count >= flushThreshold {
            flush()
        }
    }

    mutating func flush() {
        guard !buffer.isEmpty else { return }
        print(buffer, terminator: "")
        buffer.removeAll(keepingCapacity: true)
    }
}

func run() {
    guard let firstLine = readLine(),
          let capacity = Int(firstLine.trimmingSpaces()),
          capacity > 0
    else { return }

    var cache = LRUCache<String, String>(capacity: capacity)
    var output = OutputBuffer()

    while let line = readLine() {
        let tokens = line.split(separator: " ")
        guard let command = tokens.first else { continue }

        switch (command, tokens.count) {
        case ("SET", 3):
            cache.setValue(String(tokens[2]), forKey: String(tokens[1]))
        case ("GET", 2):
            output.writeLine(cache.value(forKey: String(tokens[1])) ?? "NULL")
        case ("DEL", 2):
            output.writeLine(cache.removeValue(forKey: String(tokens[1])) ? "1" : "0")
        case ("SIZE", 1):
            output.writeLine(String(cache.count))
        default:
            continue // Ignore malformed or unknown commands.
        }
    }
    output.flush()
}

extension StringProtocol {
    /// The string with leading and trailing spaces, tabs and carriage returns removed.
    func trimmingSpaces() -> SubSequence {
        let isPadding: (Character) -> Bool = { $0 == " " || $0 == "\t" || $0 == "\r" }
        guard let start = firstIndex(where: { !isPadding($0) }) else { return self[endIndex...] }
        let end = lastIndex(where: { !isPadding($0) })!
        return self[start...end]
    }
}

run()
